+    'misaki-long-term-memory': '["remember"]', 'misaki-auth-kind': 'anonymous', ...initial });
+  const sessionStorage = storage(sessionInitial);
+  const states = [], effects = [], cleanups = [], calls = [], listeners = [];
+  let cursor = 0, mounted = false, currentUser = user;
